package cse.oop2.hotelreservation.common;
import java.awt.Shape; import java.io.Serializable;
public class Room implements Serializable { private static final long serialVersionUID=1L; private String id; private transient Shape area; private boolean booked; private String ownerEmail; public Room(String id,Shape area){this.id=id;this.area=area;this.booked=false;} public Room(String id,boolean booked,String ownerEmail){this.id=id;this.booked=booked;this.ownerEmail=ownerEmail;} public String getId(){return id;} public Shape getArea(){return area;} public void setArea(Shape area){this.area=area;} public boolean isBooked(){return booked;} public void setBooked(boolean booked){this.booked=booked;} public void toggleBooking(){booked=!booked;} public String getOwnerEmail(){return ownerEmail;} public void setOwnerEmail(String email){ownerEmail=email;} }
